#!/usr/bin/env python3
from pathlib import Path
import re
ROOT = Path(__file__).resolve().parents[1]
main = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/MainActivity.kt').read_text()
voice = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/Voice.kt').read_text()
db = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/Db.kt').read_text()
items = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/ScreenItemsWarehouse.kt').read_text()
partners = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/ScreenPartnersCashChecks.kt').read_text()
invoices = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/ScreenInvoices.kt').read_text()
sheets = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/Sheets.kt').read_text()
checks = []
def test(name, ok): checks.append((name, bool(ok)))
nav = main.split('val navDefs = arrayOf(', 1)[1].split('for ((idx, d) in navDefs.withIndex())', 1)[0]
test('bottom nav has 4 destinations (More removed)', len(re.findall(r'arrayOf\("[^"\n]+"', nav)) == 4 and '"more"' not in nav)
test('center mic gap is inserted between second and third tab', 'if (idx == 2)' in main and 'UI.dp(this, 70)' in main)
test('microphone has active press animation', 'btn.animate().scaleX(0.94f).scaleY(0.94f' in main)
test('voice search opens global search populated with query', 'globalSearchSheet(this, v.query)' in voice)
voice_brain = (ROOT / 'android-native/app/src/main/java/ir/shomara/app/VoiceBrain.kt').read_text()
voice_intents = set(re.findall(r'VoiceIntent\(\s*(?:\n\s*)?\"([a-z_]+)\"', voice_brain))
executor_cases = set(re.findall(r'^\s*\"([a-z_]+)\"\s*->', voice, re.M))
test('every parsed voice intent has an executor branch (unknown falls through intentionally)', (voice_intents - {'unknown'}) <= executor_cases)
test('voice report queries keep their action button/link', '"query" -> mk(v.reply.ifEmpty' in voice and 'v.actionLabel, v.actionGo' in voice)
test('item form includes code, barcode, group, unit, price, cost, min stock, description', all(x in items for x in ['"کد کالا"','"بارکد (اختیاری)"','"گروه"','"واحد شمارش"','"قیمت فروش (تومان)"','"بهای خرید (تومان)"','"حداقل موجودی هشدار','"توضیحات"']))
test('new item form has initial stock and creates an adjustment document', 'موجودی اولیه (شروع ثبت)' in items and 'StockDoc(Db.newId("sd")' in items and 'initialQty: Long = 0L' in items)
test('item code and barcode duplicate checks exist', 'duplicateCode' in items and 'duplicateBarcode' in items)
test('new product requires sales price and cost before saving', 'برای رکورد جدید قیمت فروش باید بیشتر از صفر باشد' in items and 'برای کالای جدید بهای خرید را وارد کنید' in items)
test('item form reports success only after DB save', 'if (!saved) return@primaryBtn' in items)
test('partner form has description field', 'یادداشت / توضیحات' in partners)
test('partner form validates duplicate code/name and phone', all(x in partners for x in ['کد طرف‌حساب تکراری است','طرف‌حساب با این نام قبلاً ثبت شده است','شماره تلفن نامعتبر است']))
test('partner form checks save success', 'if (!saved) return@primaryBtn' in partners)
test('payment form requires a valid bank and checks storage result', 'صندوق یا بانک را انتخاب کنید' in partners and 'if (!saved) return@primaryBtn' in partners)
test('check form requires bank, partner and duplicate serial prevention', all(x in partners for x in ['نام بانک صادرکننده را وارد کنید','طرف‌حساب چک را انتخاب کنید','این شماره چک در همین بانک قبلاً ثبت شده است']))
test('invoice save checks persistence before showing success', 'val saved = Db.update' in invoices and 'if (!saved) return' in invoices)
test('recurring form requires warehouse and checks persistence', 'عنوان، مشتری، انبار و حداقل یک قلم لازم است' in invoices and 'if (!saved) return@primaryBtn' in invoices)
test('Db.save returns persistence status', 'fun save(): Boolean' in db)
test('partner code generator avoids existing code collisions', 'fun nextPartnerCode' in db and 'Db.nextPartnerCode(db)' in voice)
test('Db.update rolls back in-memory state on failed save', 'db = previous' in db and 'if (save()) return true' in db)
test('search result taps filter the actual destination list', all(x in sheets for x in ['act.itemsQuery = h.title','act.partnersQuery = h.title','act.invQuery = initial']))
test('master records referenced by accounting history cannot be deleted', all(x in db for x in ['fun itemHasReferences','fun partnerHasReferences']) and 'Db.itemHasReferences' in voice and 'Db.partnerHasReferences' in voice)
test('ambiguous partner deletion uses a picker instead of first fuzzy match', 'کدام طرف‌حساب؟' in voice and 'طرف‌حساب مشابه پیدا کردم؛ برای جلوگیری از حذف اشتباه' in voice)
test('voice item creation blocks duplicate name and barcode', 'این بارکد قبلاً به کالا دیگری' in voice and 'از قبل وجود دارد؛ از جستجو استفاده کنید' in voice)
test('voice partner creation blocks duplicate name', 'از قبل ثبت شده؛ برای مشاهده و استفاده از همان رکورد، جستجو کنید' in voice)
for name, ok in checks: print(('PASS' if ok else 'FAIL') + ' — ' + name)
failed = [name for name, ok in checks if not ok]
print(f'\n{len(checks)-len(failed)}/{len(checks)} static checks passed')
raise SystemExit(1 if failed else 0)
